import{c as i,$ as r,Q as o,j as s,g as t,o as n,n as l,m as c}from"./chunks/framework.Ce_49mA8.js";const v=JSON.parse('{"title":"Workspace Settings","description":"Manage master hourly rates, markups, overhead allocation, workspace cards, and workspace archival in OmniCraft ERP.","frontmatter":{"title":"Workspace Settings","description":"Manage master hourly rates, markups, overhead allocation, workspace cards, and workspace archival in OmniCraft ERP.","datePublished":"2026-08-20","dateModified":"2026-11-15","order":7},"headers":[],"relativePath":"docs/resources/space-settings.md","filePath":"docs/resources/space-settings.md","lastUpdated":1794700800000}'),d={name:"docs/resources/space-settings.md"},p={id:"workspace-settings",tabindex:"-1"};function u(h,e,g,m,f,y){const a=r("DocIcon");return o(),s("div",null,[t("h1",p,[n(a,{name:"settings"}),e[0]||(e[0]=l(" Workspace Settings ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#workspace-settings","aria-label":'Permalink to "Workspace Settings"'},"​",-1))]),e[2]||(e[2]=c('<p>The <strong>&quot;Settings&quot;</strong> tab establishes the economic foundation for your active business. This is where you configure foundational profitability benchmarks: labor valuation, planned markups, and rules for allocating indirect overhead expenses. OmniCraft ERP automatically feeds these figures into product recipes and service estimates, eliminating repetitive data entry while safeguarding against cash flow deficits.</p><p>In <strong>OmniCraft ERP</strong>, settings are strictly isolated per workspace. When running multiple independent business lines in the PRO edition (such as a custom leather atelier, an equipment repair workshop, and a retail shop), each operation retains its dedicated hourly labor rate, custom overhead categories, and an independent SQLite database.</p><hr><h2 id="core-economic-profitability-metrics" tabindex="-1">Core Economic Profitability Metrics <a class="header-anchor" href="#core-economic-profitability-metrics" aria-label="Permalink to &quot;Core Economic Profitability Metrics&quot;">​</a></h2><p>The main settings view houses two primary economic control cards: <strong>&quot;Base Pricing Parameters&quot;</strong> and <strong>&quot;Overhead Expenses&quot;</strong>.</p><h3 id="_1-master-hourly-rate" tabindex="-1">1. Master Hourly Rate <a class="header-anchor" href="#_1-master-hourly-rate" aria-label="Permalink to &quot;1. Master Hourly Rate&quot;">​</a></h3><p>The baseline accounting cost assigned to one hour of your specialized craft labor or an employed artisan&#39;s workbench time.</p><ul><li><strong>How it operates in the system:</strong> When creating a bill of materials or a service work order, the software multiplies the allocated time standard by this rate. For instance, if crafting a leather briefcase requires 2.5 labor hours and the rate is set to $30/hour, the software automatically incorporates $75 into the unit cost under &quot;Labor Cost&quot;.</li><li><strong>Why update it:</strong> Your labor rate must mirror your evolving skill level, tooling investments, and broader economic benchmarks. Periodically indexing this rate guarantees that enhanced craftsmanship translates into higher net earnings rather than getting eroded by inflation.</li><li><strong>Where it applies:</strong> Product recipe calculations, batch production on the workbench, and service work order cost sheets.</li></ul><hr><h3 id="_2-global-commercial-markup" tabindex="-1">2. Global Commercial Markup (%) <a class="header-anchor" href="#_2-global-commercial-markup" aria-label="Permalink to &quot;2. Global Commercial Markup (%)&quot;">​</a></h3><p>The baseline profit margin automatically added on top of <strong>total unit cost</strong> (materials + direct labor + overhead allocation) when generating suggested retail price tags.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Pricing Model</span><div class="formula-heading">Suggested Retail Price Formula</div></div><div class="formula-equation-box"><div class="math-line"><span class="math-var">Retail Price</span><span class="math-op">=</span><span class="math-calc-expr">Total Unit Cost</span><span class="math-op">×</span><span class="math-calc-expr"> (1 + <span class="math-fraction"><span class="math-numerator"><span class="math-var">Markup %</span></span><span class="math-denominator">100</span></span> ) </span></div></div><div class="formula-card-bottom"><p>Total unit cost incorporates raw material usage, direct labor valuation, and allocated workshop overheads.</p></div></div><ul><li><strong>Operational flexibility:</strong> The global markup acts as a system-wide default recommendation. Within any individual product or service card, you retain the freedom to override the final selling price manually (for example, promotional sales or limited collector editions).</li><li><strong>Economic purpose:</strong> The markup constitutes your financial safety cushion. It absorbs unforeseen material defects, scrap allowances, seasonal demand fluctuations, and customer acquisition costs.</li></ul><hr><h3 id="_3-overhead-expenses-indirect-business-costs" tabindex="-1">3. Overhead Expenses (Indirect Business Costs) <a class="header-anchor" href="#_3-overhead-expenses-indirect-business-costs" aria-label="Permalink to &quot;3. Overhead Expenses (Indirect Business Costs)&quot;">​</a></h3><p>A sustainable craft operation encompasses far more than raw materials and bench time. Studio lease payments, electricity, taxes, packaging supplies, equipment depreciation, software subscriptions, and payment processing fees require consistent funding.</p><p>In <strong>OmniCraft ERP</strong>, you maintain a custom ledger of overhead expense categories that are <strong>automatically distributed across every manufactured item or completed order</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Category Type</th><th style="text-align:left;">Calculation Method</th><th style="text-align:left;">Typical Real-World Applications</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Percentage Rate (%)</strong></td><td style="text-align:left;">Proportion of raw material cost or base prime cost</td><td style="text-align:left;">Payment processing fees, marketplace commissions, outbound freight, packaging consumables</td></tr><tr><td style="text-align:left;"><strong>Fixed Amount ($)</strong></td><td style="text-align:left;">Constant monetary surcharge added per finished item</td><td style="text-align:left;">Studio lease (allocated across planned unit volume), branded labels, guarantee certificates, boxes</td></tr></tbody></table><h4 id="managing-expense-categories" tabindex="-1">Managing Expense Categories <a class="header-anchor" href="#managing-expense-categories" aria-label="Permalink to &quot;Managing Expense Categories&quot;">​</a></h4><ul><li><strong>Adding:</strong> Click <strong>&quot;Add Category&quot;</strong>, enter a clear title (e.g., <em>&quot;Studio Lease&quot;</em> or <em>&quot;Branded Packaging&quot;</em>), select the allocation method (percentage or fixed amount), and specify the value. The entry populates the ledger immediately.</li><li><strong>Editing and Deleting:</strong> Modify allocations or remove obsolete expense lines anytime using the inline action buttons.</li></ul><div class="warning custom-block"><p class="custom-block-title">Historical Record Integrity</p><p>Deleting or updating an overhead category <strong>does not retroactively recalculate archived sales or historical production batches</strong>. Updated values apply strictly to subsequent calculations. This protects historical cash flow ledgers and balance sheet snapshots from retroactive distortions.</p></div><hr><h3 id="_4-selective-date-input-field-visibility" tabindex="-1">4. Selective Date Input Field Visibility <a class="header-anchor" href="#_4-selective-date-input-field-visibility" aria-label="Permalink to &quot;4. Selective Date Input Field Visibility&quot;">​</a></h3><p>By default, manual date pickers across operational forms remain concealed to maximize typing speed: the system defaults to the current day.</p><p>If your workflow involves backdating incoming material shipments, entering past receipts, or scheduling future dispatches:</p><ol><li>Expand the <strong>&quot;Date Input Configuration&quot;</strong> section;</li><li>Check the relevant operational modules (Warehouse, Cash Flow, Sales, Work Orders);</li><li>Click <strong>&quot;Save Settings&quot;</strong>.</li></ol><hr><h2 id="workspace-profile-administration" tabindex="-1">Workspace Profile &amp; Administration <a class="header-anchor" href="#workspace-profile-administration" aria-label="Permalink to &quot;Workspace Profile &amp; Administration&quot;">​</a></h2><p>The workspace passport itself is managed through the lateral slide-out drawer (workspace selector at the top left of the interface):</p><ul><li><strong>Custom Title:</strong> Assign a distinctive identity (<em>&quot;Heritage Tannery&quot;</em>, <em>&quot;Precision Audio Lab&quot;</em>, <em>&quot;Ceramic Studio&quot;</em>). This title displays in the window title bar and on printed workshop documents.</li><li><strong>Description &amp; Scope:</strong> Record the operational charter and internal workbench guidelines.</li><li><strong>Industry Profile:</strong> Select your primary operational orientation — &quot;Craft &amp; Manufacturing&quot;, &quot;Services &amp; Repairs&quot;, or &quot;Retail&quot;. OmniCraft ERP tailors module headers and terminology to match the chosen orientation.</li></ul><hr><h2 id="workspace-lifecycle-archival-workflow" tabindex="-1">Workspace Lifecycle &amp; Archival Workflow <a class="header-anchor" href="#workspace-lifecycle-archival-workflow" aria-label="Permalink to &quot;Workspace Lifecycle &amp; Archival Workflow&quot;">​</a></h2><p>The system provides a resilient lifecycle protocol that prevents accidental data loss:</p><ol><li><strong>Single Active Workspace Rule in Standard Edition:</strong> The standard edition focuses your attention on a single active business venture without dashboard clutter. When closing a seasonal venture or retiring a project, the current workspace moves to the archive, freeing capacity for a new initiative.</li><li><strong>Archival Over Hard Deletion:</strong> Archiving a workspace freezes its entire operational state (raw material balances, asset purchase values, cash transactions, finished inventory, and customer rosters). Zero records are erased.</li><li><strong>Safety Grace Period:</strong> Immediately following archival, a safety window opens. If an operation was triggered accidentally, you can restore the workspace back to active status with a single click without restrictions.</li><li><strong>Concurrent Multi-Tenancy in PRO Edition:</strong> The PRO license unlocks unrestricted active workspaces. You can run dozens of distinct ventures concurrently and alternate between them instantly.</li><li><strong>Permanent Deletion:</strong> Hard deletion is accessible exclusively from the archived ledger and requires explicit confirmation through a safety prompt.</li></ol><hr><h2 id="engineering-reliability-data-integrity" tabindex="-1">Engineering Reliability &amp; Data Integrity <a class="header-anchor" href="#engineering-reliability-data-integrity" aria-label="Permalink to &quot;Engineering Reliability &amp; Data Integrity&quot;">​</a></h2><p>All workspace accounting adheres to strict architectural safety standards:</p><ul><li><strong>Database Isolation:</strong> Every workspace operates on an isolated local SQLite file (<code>workspace_&lt;id&gt;.db</code>). An anomaly or archival action in one workspace cannot corrupt neighboring project records.</li><li><strong>Integer Currency Scaling:</strong> All labor rates, percentage markups, and overhead rates are persisted as scaled 64-bit integers with a 10,000 multiplier. This eliminates floating-point rounding anomalies, sub-cent leakage, and compounding rounding errors over multi-year operational cycles.</li><li><strong>Local Backup Discipline:</strong> We recommend creating periodic local copies of your workspace database files to external media prior to major rate revisions or tooling overhauls.</li></ul><hr><h2 id="matrix-how-settings-impact-workshop-economics" tabindex="-1">Matrix: How Settings Impact Workshop Economics <a class="header-anchor" href="#matrix-how-settings-impact-workshop-economics" aria-label="Permalink to &quot;Matrix: How Settings Impact Workshop Economics&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Parameter</th><th style="text-align:left;">Application Point</th><th style="text-align:left;">Risk if Underestimated</th><th style="text-align:left;">Risk if Overestimated</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Master Labor Rate</strong></td><td style="text-align:left;">Labor valuation in recipe calculations and work orders</td><td style="text-align:left;">Undervaluing craft labor, false perception of profitability</td><td style="text-align:left;">Setting retail prices above market tolerance</td></tr><tr><td style="text-align:left;"><strong>Overhead Expenses</strong></td><td style="text-align:left;">Total unit cost per finished product</td><td style="text-align:left;">Cash flow deficits: paper profits get consumed by lease and tax obligations</td><td style="text-align:left;">Rejecting viable standard jobs due to inflated cost thresholds</td></tr><tr><td style="text-align:left;"><strong>Commercial Markup</strong></td><td style="text-align:left;">Recommended catalog retail price</td><td style="text-align:left;">Insufficient capital for business expansion and marketing</td><td style="text-align:left;">Depressed conversion rates and extended sales cycles</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Benchmark Review Frequency</p><p>Avoid erratic weekly revisions of your core parameters. Volatile adjustments distort historical margin comparisons. A sound workshop cadence is reviewing settings <strong>once per quarter</strong> or following substantial structural milestones (relocating premises, adopting higher-efficiency machinery, or major supplier price hikes).</p></div>',42))])}const k=i(d,[["render",u]]);export{v as __pageData,k as default};
